static void microwave_unit_eventqueue_init(microwave_unit_eventqueue * eq, microwave_unit_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer microwave_unit_eventqueue_size(microwave_unit_eventqueue * eq)
{
	return eq->size;
}

static microwave_unit_event microwave_unit_eventqueue_pop(microwave_unit_eventqueue * eq)
{
	microwave_unit_event event;
	if(microwave_unit_eventqueue_size(eq) <= 0) {
		microwave_unit_event_init(&event, Microwave_Unit_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean microwave_unit_eventqueue_push(microwave_unit_eventqueue * eq, microwave_unit_event ev)
{
	if(microwave_unit_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void microwave_unit_event_init(microwave_unit_event * ev, Microwave_UnitEventID name)
{
	ev->name = name;
}

static void microwave_Unit_add_event_to_queue(microwave_unit_eventqueue * eq, Microwave_UnitEventID name)
{
	microwave_unit_event event;
	microwave_unit_event_init(&event, name);
	microwave_unit_eventqueue_push(eq, event);
}

